package main

import "fmt"

// out is send-only: the compiler forbids receiving or closing here.
func produce(out chan<- int, n int) {
	for i := 1; i <= n; i++ {
		out <- i
	}
}

func main() {
	ch := make(chan int, 3)
	produce(ch, 3)
	fmt.Println(<-ch, <-ch, <-ch)
	// Output: 1 2 3
}

package main

import "fmt"

// in is receive-only: range is fine, sending would not compile.
func sum(in <-chan int) int {
	total := 0
	for v := range in {
		total += v
	}
	return total
}

func main() {
	ch := make(chan int, 3)
	ch <- 1
	ch <- 2
	ch <- 3
	close(ch)
	fmt.Println(sum(ch))
	// Output: 6
}

package main

import (
	"fmt"
	"sync"
)

func main() {
	jobs := []int{1, 2, 3}
	// Buffer sized to the work: every worker sends once without blocking.
	results := make(chan int, len(jobs))
	var wg sync.WaitGroup
	for _, j := range jobs {
		wg.Add(1)
		go func(j int) { defer wg.Done(); results <- j * j }(j)
	}
	wg.Wait()
	close(results)
	total := 0
	for r := range results {
		total += r
	}
	fmt.Println(total)
	// Output: 14
}

