package solution

import "sync"

func Solve(nums []int, limit int) []int {
	if limit < 1 {
		limit = 1
	}
	res := make([]int, len(nums))      // each index written once
	sem := make(chan struct{}, limit)  // buffered semaphore
	var wg sync.WaitGroup
	for i, n := range nums {
		wg.Add(1)
		go func(idx, val int) {
			defer wg.Done()
			sem <- struct{}{}          // acquire (blocks past `limit`)
			defer func() { <-sem }()   // release
			res[idx] = val * val       // distinct index: no data race
		}(i, n)
	}
	wg.Wait()
	return res
}

