package solution

import (
	"reflect"
	"testing"
)

func TestSolve(t *testing.T) {
	cases := []struct {
		in    []int
		limit int
		want  []int
	}{
		{[]int{1, 2, 3, 4}, 2, []int{1, 4, 9, 16}},
		{[]int{5}, 1, []int{25}},
		{[]int{}, 3, []int{}},
	}
	for _, c := range cases {
		got := Solve(c.in, c.limit)
		if len(c.want) == 0 && len(got) == 0 {
			continue
		}
		if !reflect.DeepEqual(got, c.want) {
			t.Errorf("Solve(%v,%d)=%v want %v", c.in, c.limit, got, c.want)
		}
	}
}

