func main() {
	ch := make(chan int, 2)
	go func() {                 // consumer runs concurrently
		for i := 0; i < 3; i++ {
			fmt.Println(<-ch)   // drains as the producer sends
		}
	}()
	for i := 0; i < 3; i++ {
		ch <- i             // sends now make progress
	}
}

func Worker(jobs <-chan int, results chan<- int) {
	for n := range jobs {   // receive-only: drains until jobs is closed
		results <- n * n    // send-only: can't receive or close here
	}
}

func TrySend(ch chan<- int, v int) bool {
	select {
	case ch <- v: // succeeds only if the buffer has room
		return true
	default: // buffer full: return at once instead of blocking
		return false
	}
}
